// JS booleans are not a number subtype: object keys coerce to strings, and
// Map uses SameValueZero (no type coercion), so 1 and true never collide.
const obj = { 1: "a", true: "b" };
console.log(obj, Object.keys(obj));
const m = new Map([[1, "a"], [true, "b"]]);
console.log(m.size, [...m.keys()]);
console.log(true + true); // arithmetic coercion still matches Python here
